import { Table, StringColumn, ReferenceColumn, GuidColumn, IntegerColumn } from '../../db'

export const sp_row = Table({
    allowWebServiceAccess: true,
    display: 'order',
    extends: 'sys_metadata',
    label: 'Row',
    name: 'sp_row',
    schema: {
        class_name: StringColumn({
            label: 'CSS class',
        }),
        sp_column: ReferenceColumn({
            cascadeRule: 'delete',
            label: 'Column',
            referenceTable: 'sp_column',
        }),
        sys_id: GuidColumn({
            columnType: 'GUID',
            label: 'Sys ID',
            maxLength: 32,
            primary: true,
        }),
        semantic_tag: StringColumn({
            choices: {
                main: {
                    label: 'Main',
                    sequence: 1,
                },
            },
            dropdown: 'dropdown_with_none',
            label: 'Semantic tag',
        }),
        sp_container: ReferenceColumn({
            cascadeRule: 'delete',
            label: 'Container',
            referenceTable: 'sp_container',
        }),
        order: IntegerColumn({
            label: 'Order',
        }),
    },
})
